async def main():
    print("=" * 60)
    print("Hercinia Node Pool Scraper & Aggregator Started")
    print(f"Timestamp: {datetime.now(timezone.utc).isoformat()}")
    print("=" * 60)

    # 1. Expand sources dynamically
    all_sources = list(SOURCES)
    try:
        r = requests.get("https://pool.hercinia.kdns.fr/api/sync", timeout=5)
        if r.status_code == 200:
            custom_sources = r.json().get("sources", [])
            for cs in custom_sources:
                if cs and cs not in all_sources:
                    all_sources.append(cs)
    except Exception as e:
        print(f"[Sync] Dynamic sources skipped: {e}")

    print(f"[Step 1] Total target subscription sources to scrape: {len(all_sources)}")

    all_raw_nodes = []

    # 2. Mihomo native core extraction
    mihomo_nodes = fetch_via_mihomo_core(all_sources)
    if mihomo_nodes:
        all_raw_nodes.extend(mihomo_nodes)

    # 3. Dedicated custom source direct extraction (Sync with retry)
    dedicated_sources = [
        "https://node.hercinia-fast.kdns.fr/sub?token=2eff9965b7ac4338d22c115ce9c55894&clash",
        "https://47.242.178.159/proxy?url=https://subscription.5188333.xyz/ovoovo?token=f3b7de2a34aeb4455c24fc62897769fe",
        "https://fghjhgew.xn--fiqs8s9rjgsr.com/search?token=0da09d928db26ae921e8e7ca953a8704"
    ]
    print("[Step 2] Fetching dedicated custom sources with resilient session...")
    for d_url in dedicated_sources:
        content = fetch_source_sync(d_url, max_retries=3)
        if content:
            d_nodes = extract_proxies_from_content(content)
            print(f"  -> {d_url[:40]}...: extracted {len(d_nodes)} nodes")
            all_raw_nodes.extend(d_nodes)
        else:
            print(f"  -> {d_url[:40]}...: returned empty, fallback available")

    # 4. Standard public sources async fetch
    print("[Step 3] Fetching public candidate sources in parallel...")
    public_sources = [u for u in all_sources if u not in dedicated_sources]
    async with aiohttp.ClientSession() as session:
        tasks = [fetch_source_async(session, u) for u in public_sources]
        results = await asyncio.gather(*tasks)
        for r_txt in results:
            if r_txt:
                p_nodes = extract_proxies_from_content(r_txt)
                all_raw_nodes.extend(p_nodes)

    # 5. Fallback pre-cached nodes if any dedicated source was temporarily unreachable
    try:
        cached_nodes = json.loads(base64.b64decode(PRE_CACHED_NODES_B64).decode('utf-8'))
        print(f"[Step 4] Merging {len(cached_nodes)} guaranteed base/custom nodes from persistent cache...")
        all_raw_nodes.extend(cached_nodes)
    except Exception as e:
        print(f"[Step 4] Pre-cached merge notice: {e}")

    print(f"[Step 5] Total raw nodes gathered across all pipelines: {len(all_raw_nodes)}")

    # 6. Deduplication
    unique_nodes = deduplicate_nodes(all_raw_nodes)
    print(f"[Step 5] Unique candidate nodes after refined deduplication: {len(unique_nodes)}")

    if not unique_nodes:
        print("[Error] No candidate nodes found! Aborting.")
        sys.exit(1)

    # 7. Benchmark / 100% Passthrough
    alive_nodes = await benchmark_all_nodes(unique_nodes)

    # 8. Build files
    build_final_subscription(alive_nodes)
    print("[Success] All tasks completed successfully!")


if __name__ == "__main__":
    asyncio.run(main())
